package vista;
import controlador.PrestamoController;import dao.EstudianteDAO;import dao.LibroDAO;import modelo.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.List;
public class PrestamosFrame extends JFrame {private final Usuario usuario;private final PrestamoController ctrl=new PrestamoController();private final EstudianteDAO edao=new EstudianteDAO();private final LibroDAO ldao=new LibroDAO();private final DefaultTableModel model=new DefaultTableModel(new Object[]{"ID","Estudiante","Libro","Fecha préstamo","Vencimiento","Devuelto","ID estudiante","ID libro"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
 public PrestamosFrame(Usuario u){super("Préstamos y devoluciones");usuario=u;setSize(950,500);setLocationRelativeTo(null);setLayout(new BorderLayout());add(new JScrollPane(table),BorderLayout.CENTER);JPanel p=new JPanel();JButton refresh=new JButton("Actualizar"),loan=new JButton("Registrar préstamo"),ret=new JButton("Registrar devolución");p.add(refresh);p.add(loan);p.add(ret);if(!u.esBibliotecario()){loan.setText("Solicitar préstamo");}add(p,BorderLayout.SOUTH);refresh.addActionListener(e->load());loan.addActionListener(e->formLoan());ret.addActionListener(e->returnBook());load();}
 private void msg(String s){JOptionPane.showMessageDialog(this,s);}private void load(){try{model.setRowCount(0);for(Prestamo p:ctrl.listar())if(usuario.esBibliotecario()||edao.listar().stream().anyMatch(es->es.getId()==p.getIdEstudiante()&&es.getRut().equals(usuario.getRut())))model.addRow(new Object[]{p.getId(),p.getEstudiante(),p.getLibro(),p.getFechaPrestamo(),p.getFechaDevolucion(),p.isDevuelto()?"Sí":"No",p.getIdEstudiante(),p.getIdLibro()});}catch(Exception e){msg("Error al cargar préstamos: "+e.getMessage());}}
 private void formLoan(){try{List<Estudiante> es=edao.listar();List<Libro> ls=ldao.listar();if(!usuario.esBibliotecario())es.removeIf(est->!est.getRut().equals(usuario.getRut()));JComboBox<Estudiante> ec=new JComboBox<>(es.toArray(new Estudiante[0]));JComboBox<Libro> lc=new JComboBox<>(ls.stream().filter(l->l.getStock()>0).toArray(Libro[]::new));if(ec.getItemCount()==0||lc.getItemCount()==0){msg("Se necesita al menos un estudiante y un libro con stock disponible.");return;}JPanel p=new JPanel(new GridLayout(2,2,6,6));p.add(new JLabel("Estudiante"));p.add(ec);p.add(new JLabel("Libro disponible"));p.add(lc);if(JOptionPane.showConfirmDialog(this,p,"Nuevo préstamo (7 días)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;Estudiante e=(Estudiante)ec.getSelectedItem();Libro l=(Libro)lc.getSelectedItem();setBusy(true);new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{ctrl.prestar(l.getId(),e.getId());return null;}protected void done(){setBusy(false);try{get();msg("Préstamo registrado. Fecha de vencimiento: dentro de 7 días.");load();}catch(Exception ex){msg("No se pudo registrar el préstamo: "+(ex.getCause()==null?ex.getMessage():ex.getCause().getMessage()));}}}.execute();}catch(Exception e){msg("Error: "+e.getMessage());}}
 private void setBusy(boolean b){setCursor(Cursor.getPredefinedCursor(b?Cursor.WAIT_CURSOR:Cursor.DEFAULT_CURSOR));}
 private void returnBook(){int r=table.getSelectedRow();if(r<0){msg("Selecciona un préstamo.");return;}if("Sí".equals(model.getValueAt(r,5))){msg("Ese préstamo ya está devuelto.");return;}int id=(int)model.getValueAt(r,0);setBusy(true);new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{ctrl.devolver(id);return null;}protected void done(){setBusy(false);try{get();msg("Devolución registrada y stock actualizado.");load();}catch(Exception e){msg("Error en devolución: "+(e.getCause()==null?e.getMessage():e.getCause().getMessage()));}}}.execute();}
}